"""
Integration Contract Test for Google News RSS API Client

This module contains contract tests that hit the live Google News RSS API to
verify that the third-party service behaves exactly as the GoogleRSSClient 
expects. 

Key Details & Architecture:
- Live Contract Validation: This is a non-mocked test. It validates the end-to-end 
  live API contract, ensuring that the URL generated by the client is reachable, 
  returns valid RSS/XML, is successfully parsed by `feedparser`, and produces the 
  data structure required by downstream dependencies (e.g., `NewsService.get_business_news`).
- Test Boundaries: Asserts focus strictly on the structural contract (e.g., the presence 
  of `feed` and `entries` fields) rather than exact content, as news feeds change constantly.
- Multilingual Scope: Validates behavior across both supported locales: ID and US.
- CI/CD & Isolation: Because these tests rely on an external service, they are 
  isolated from the standard unit-test suite. They are marked with `@pytest.mark.external` 
  allowing them to be excluded during normal CI runs using `pytest -m "not external"`. 
  They should be run exclusively on-demand or via scheduled integration pipelines.
- Resilience: Includes network guards to gracefully skip execution if the external 
  service is unreachable.
"""
import pytest
import httpx


def pytest_configure(config):
    """Register the 'external' marker to avoid warnings."""
    config.addinivalue_line(
        "markers",
        "external: marks tests that hit real third-party APIs (deselect with '-m \"not external\"')",
    )


@pytest.fixture(scope="session")
def network_available() -> bool:
    """Skip the whole external suite if we have no internet access."""
    try:
        httpx.get("https://news.google.com", timeout=5.0)
        return True
    except httpx.HTTPError:
        return False


@pytest.fixture(autouse=True)
def skip_if_no_network(network_available):
    if not network_available:
        pytest.skip("No network connectivity — skipping external API contract test.")